    {
        "google-adk",
    }
)

# Never read more than this many bytes from a single dependency file. This
# bounds the work done for pathologically large lock/requirements files; any
# content beyond the cap is silently ignored.
_MAX_READ_BYTES = 5 * 1024 * 1024

# Version specifier used when a package is present but its version is unknown
# (e.g. it only appears as an extras marker, or has no version constraint).
_UNKNOWN = "unknown"


def _read_capped(path: pathlib.Path) -> str | None:
    """Read up to `_MAX_READ_BYTES` bytes of a text file.

    Returns the decoded text, or `None` if the file cannot be read. Content
    beyond the cap is discarded rather than raising.
    """
    try:
        with path.open("rb") as f:
            raw = f.read(_MAX_READ_BYTES)
    except OSError:
        return None
    return raw.decode("utf-8", errors="replace")


def _normalize(name: str) -> str:
    """Normalize a package name per PEP 503 for comparison."""
    return re.sub(r"[-_.]+", "-", name).lower()


