_NORMALIZED_TRACKED = {_normalize(name): name for name in TRACKED_PACKAGES}


def _match_tracked(name: str) -> str | None:
    """Return the canonical tracked package name for `name`, if tracked."""
    return _NORMALIZED_TRACKED.get(_normalize(name))


def _find_in_uv_lock(text: str) -> dict[str, str]:
    """Return {canonical_name: exact_version} for tracked packages in a uv.lock."""
    found: dict[str, str] = {}
    try:
        data = tomllib.loads(text)
    except (tomllib.TOMLDecodeError, ValueError):
        return found
    packages = data.get("package")
    if not isinstance(packages, list):
        return found
    for pkg in packages:
        if not isinstance(pkg, dict):
            continue
        name = pkg.get("name")
        if not isinstance(name, str):
            continue
        tracked = _match_tracked(name)
        if tracked is None:
            continue
        version = pkg.get("version")
        found[tracked] = version if isinstance(version, str) else _UNKNOWN
    return found


def _spec_from_requirement(entry: str, tracked_normalized: str) -> str:
    """Extract the version specifier for a tracked package from a dep string.

    Handles PEP 508 style entries such as `google-adk>=0.5,<2`,
    `google-adk==1.0.0`, `google-adk` (bare), and extras markers like
    `other-pkg[google-adk]>=0.0.1` (which yields `unknown`).
    """
