    match = re.match(r"^\s*([A-Za-z0-9][A-Za-z0-9._-]*)\s*(\[[^\]]*\])?\s*(.*)$", entry)
    if match and _normalize(match.group(1)) == tracked_normalized:
        spec = match.group(3).strip()
